import { defineComponent, onBeforeMount, onMounted, ref } from 'vue';

export default defineComponent({
  setup() {
    const text = ref('outer');
    const vLoading = ref(true);
    const isShowDialog = ref(false);
    const info = ref({
      text: '',
      user: {
        username: '',
        password: '',
      },
    });

    function testFunc() {
      console.log('test func');
    }

    onBeforeMount(() => {
      console.log('will mount');
    });

    // `this` is the runtime scope: data sources, utils, i18n
    onMounted(() => {
      this.dataSourceMap.info
        .load()
        .then((res) => {
          console.log(res);
          info.value = res;
        })
        .catch((err) => {
          console.log(err);
        });
      console.log('did mount');
    });

    return { text, vLoading, isShowDialog, info, testFunc };
  },
});
